    {
      "ref": "[R214]",
      "area": "content",
      "claim": "A parent reports seeing avatars with excessive skin and encountering predators in games like mm2.",
      "stance": "risk",
      "quote": "So I was playing Roblox then theses weirds avatars where showing a lot of skin like in mm2 but then I reported them but nothing work and some of them are KIDS but Roblox has good games and keep doing the good work."
    },
    {
      "ref": "[R223]",
      "area": "money",
      "claim": "A parent reports being scammed out of 216 Robux after purchasing a mini plush.",
      "stance": "risk",
      "quote": "I buy a mini plush next second it’s gone you scam me 216 Robux I took it off for one second really the heck"
    },
    {
      "ref": "[R224]",
      "area": "money",
      "claim": "A parent reports losing purchased Robux immediately after buying a mini plush.",
      "stance": "risk",
      "quote": "I buy a mini plush next second it’s gone you scam me 216 Robux I took it off for one second really the heck"
    },
    {
      "ref": "[R242]",
      "area": "content",
      "claim": "A parent reports that voice chat was suspended after reporting a child crying, while predators remain unchecked.",
      "stance": "risk",
      "quote": "So I got reported for telling this kid to be quiet because he kept crying in voice chat and he reported me and it went through getting my voice chat suspended for 1 year.Roblox can do accept any dumb report but they can’t stop the child predators and E-Daters."
    },
    {
      "ref": "[R257]",
      "area": "data",
      "claim": "A parent reports that Roblox uses AI to collect facial or ID data, which is described as unsafe and disgusting.",
      "stance": "risk",
      "quote": "Their safety on this game is incredibly bad. They decided to have us put our faces or ID into Artificial Intelligence. Which is disgustingly stupid and unsafe."
    },
    {
      "ref": "[R294]",
      "area": "age_gating",
      "claim": "A parent reports that Roblox's age verification incorrectly labels them as 11 when they are 16, and enforces a 4-hour usage limit.",
      "stance": "risk",
      "quote": "Why is there a time limit\nI have a PC and I often leave it on for offline afk uses, and they set like a 4 hr limit. Plus they put me as 11 when I’m actually 16"
    },
    {
      "ref": "[R266]",
      "area": "contact",
      "claim": "A parent reports losing access to their child's account after a friend logged in and deleted it, preventing them from playing.",
      "stance": "risk",
      "quote": "Roblox is fun, but I lost my account and I want it back\nRoblox is really fun like me and my sister like to play on it but my friend logged onto my account and deleted my account and then few days later. I want it back because it has like most valuable things on there and then I can’t get it back."
    },
    {
      "ref": "[R282]",
      "area": "content",
      "claim": "A parent reports that predators (referred to as 'predator47_') attempted to bomb them in Roblox.",
